INSERT INTO incident (incident_id, name, incident_date, country_id, location_name, latitude, longitude, environment, source_type, cause_id, volume_barrels, volume_confidence, fatalities, status, summary) VALUES
  (1, 'Deepwater Horizon', '2010-04-20', 1, 'Macondo Prospect, Gulf of Mexico', 28.7381, -88.3659, 'marine', 'offshore_platform', 1, 3190000, 'high', 11, 'closed', 'Explosion and sinking of a drilling rig after a well blowout; oil flowed for about 87 days. Largest marine spill in history by most estimates. Volume is the court-accepted figure of about 3.19 million barrels; the US government earlier estimated 4.9 million.'),
  (2, 'Exxon Valdez', '1989-03-24', 1, 'Prince William Sound, Alaska', 60.83, -146.86, 'marine', 'tanker', 3, 257000, 'high', 0, 'closed', 'Tanker ran aground on Bligh Reef; one of the most studied spills, with long-lasting damage to Alaska''s coastline and fisheries.'),
  (3, 'Gulf War oil spill', '1991-01-19', 2, 'Persian Gulf off Kuwait', 28.95, 48.7, 'marine', 'deliberate', 8, 6000000, 'low', 0, 'closed', 'Oil deliberately released into the Persian Gulf during the Gulf War; estimates vary widely between roughly 4 and 11 million barrels. NOAA gives a range of 6 to 8 million barrels.'),
  (4, 'Ixtoc I', '1979-06-03', 3, 'Bay of Campeche', 19.41, -92.33, 'marine', 'offshore_platform', 1, 3300000, 'medium', 0, 'closed', 'Exploratory well blowout that flowed for nearly ten months before being capped.'),
  (5, 'Atlantic Empress', '1979-07-19', 4, 'Off Tobago', 11.3, -60.9, 'marine', 'tanker', 2, 2100000, 'medium', 26, 'closed', 'Two tankers collided during a tropical storm; Atlantic Empress burned and later sank in the largest ship-sourced spill on record.'),
  (6, 'Amoco Cadiz', '1978-03-16', 5, 'Off Portsall, Brittany', 48.6, -4.72, 'marine', 'tanker', 4, 1600000, 'high', 0, 'closed', 'Supertanker lost steering and ran aground off Brittany, breaking up and spilling its entire cargo.'),
  (7, 'Torrey Canyon', '1967-03-18', 6, 'Seven Stones reef, off Cornwall', 50.03, -6.07, 'marine', 'tanker', 3, 870000, 'medium', 1, 'closed', 'Supertanker struck Seven Stones reef; an early major tanker spill that prompted modern maritime pollution conventions.'),
  (8, 'Prestige', '2002-11-13', 21, 'Off Galicia', 43.0, -9.9, 'marine', 'tanker', 6, 400000, 'medium', 0, 'closed', 'Single-hulled tanker developed a hull crack in a storm and sank after being refused port; oil reached the Spanish and French coasts.'),
  (9, 'Erika', '1999-12-12', 5, 'Bay of Biscay, off Brittany', 47.3, -5.5, 'marine', 'tanker', 6, 130000, 'medium', 0, 'closed', 'Tanker broke in two in a storm, polluting the French Atlantic coast with heavy fuel oil.'),
  (10, 'Sea Empress', '1996-02-15', 6, 'Milford Haven, Wales', 51.69, -5.18, 'marine', 'tanker', 3, 530000, 'high', 0, 'closed', 'Tanker grounded at the entrance to Milford Haven beside a national park coastline; one of the UK''s worst spills.'),
  (11, 'Braer', '1993-01-05', 6, 'Garths Ness, Shetland', 59.88, -1.33, 'marine', 'tanker', 4, 620000, 'high', 0, 'closed', 'Tanker lost engine power and grounded in a storm; light crude was largely dispersed by heavy seas.'),
  (12, 'Ekofisk Bravo blowout', '1977-04-22', 7, 'Ekofisk field, North Sea', 56.567, 3.2, 'marine', 'offshore_platform', 1, 202000, 'high', 0, 'closed', 'Blowout during a workover at a North Sea platform; oil flowed for about a week before being capped.'),
  (13, 'Santa Barbara oil spill', '1969-01-28', 1, 'Santa Barbara Channel, California', 34.34, -119.62, 'marine', 'offshore_platform', 1, 100000, 'medium', 0, 'closed', 'Offshore platform blowout that fouled Southern California beaches and helped spark the modern US environmental movement.'),
  (14, 'Lakeview Gusher', '1910-03-14', 1, 'Midway-Sunset field, California', 35.0914, -119.4014, 'land', 'onshore_well', 1, 9000000, 'medium', 0, 'closed', 'Gusher that flowed for about 18 months; the largest accidental onshore spill on record, much of it held in earthen sumps.'),
  (15, 'Kalamazoo River spill (Line 6B)', '2010-07-25', 1, 'Marshall, Michigan', 42.27, -84.96, 'freshwater', 'pipeline', 5, 20000, 'high', 0, 'closed', 'Pipeline rupture released heavy crude into Talmadge Creek and the Kalamazoo River; cleanup took years.'),
  (16, 'Mayflower pipeline spill', '2013-03-29', 1, 'Mayflower, Arkansas', 34.95, -92.43, 'land', 'pipeline', 4, 3190, 'medium', 0, 'closed', 'Pipeline seam failure sent crude through a residential subdivision. Early press reports said 5,000 barrels; the corrected estimate is about 134,000 gallons.'),
  (17, 'Tioga pipeline spill', '2013-09-29', 1, 'Tioga, North Dakota', 48.4, -102.94, 'land', 'pipeline', 4, 20600, 'medium', 0, 'closed', 'Pipeline leak contaminated farmland and went undetected by the operator''s monitoring until a farmer found it.'),
  (18, 'Refugio Beach spill (Line 901)', '2015-05-19', 1, 'Refugio State Beach, California', 34.46, -120.07, 'marine', 'pipeline', 5, 2934, 'high', 0, 'closed', 'Corroded pipeline ruptured near the coast and oil reached the Pacific through a culvert.'),
  (19, 'Keystone pipeline Kansas spill', '2022-12-07', 1, 'Washington County, Kansas', 39.8422, -96.9955, 'freshwater', 'pipeline', 4, 12937, 'medium', 0, 'closed', 'Pipeline failure released crude into Mill Creek and surrounding land; one of the larger onshore crude spills in recent US history.'),
  (20, 'Taylor Energy platform leak', '2004-09-15', 1, 'Mississippi Canyon 20, Gulf of Mexico', 28.94, -88.97, 'marine', 'offshore_platform', 7, NULL, 'low', 0, 'ongoing', 'Wells damaged by a Hurricane Ivan mudslide have leaked continuously since 2004; one of the longest-running offshore leaks.'),
  (21, 'Red Hill fuel leak', '2021-11-20', 1, 'Red Hill, Oahu, Hawaii', 21.37, -157.93, 'land', 'storage_facility', 10, 333, 'low', 0, 'contained', 'Fuel leaks from a Navy bulk storage facility contaminated the drinking-water system serving military housing. Volume is the 14,000 gallon fuel and water mix reported for 20 Nov 2021; an earlier May 2021 release was larger.'),
  (22, 'Lac-Megantic rail disaster', '2013-07-06', 8, 'Lac-Megantic, Quebec', 45.58, -70.88, 'land', 'rail', 10, 37700, 'medium', 47, 'closed', 'Runaway crude oil train derailed and exploded in the town centre.'),
  (23, 'Rainbow Pipeline spill', '2011-04-29', 8, 'Little Buffalo, Alberta', 56.0, -115.9, 'land', 'pipeline', 4, 28000, 'medium', 0, 'closed', 'Pipeline rupture in a remote area of northern Alberta.'),
  (24, 'Husky Saskatchewan River spill', '2016-07-20', 8, 'Near Maidstone, Saskatchewan', 53.08, -109.28, 'freshwater', 'pipeline', 7, 1415, 'medium', 0, 'closed', 'Pipeline rupture from ground movement; downstream towns had to find alternate water supplies.'),
  (25, 'Guanabara Bay oil spill', '2000-01-18', 9, 'Guanabara Bay, Rio de Janeiro', -22.8, -43.15, 'marine', 'pipeline', 4, 8000, 'medium', 0, 'closed', 'Refinery pipeline rupture spilled into Guanabara Bay, affecting mangroves and fishing communities.'),
  (26, '2019 Brazil coast oil spill', '2019-08-30', 9, 'Northeast coast of Brazil', -9.0, -35.0, 'marine', 'unknown', 11, 36000, 'low', 0, 'unknown', 'Crude oil of unclear origin washed up on hundreds of beaches in northeastern Brazil; the source was never conclusively established.'),
  (27, 'Ventanilla oil spill', '2022-01-15', 10, 'Ventanilla, Callao', -11.95, -77.15, 'marine', 'tanker', 7, 11900, 'high', 0, 'closed', 'Tanker unloading at a refinery spilled crude when abnormal waves from the Tonga volcanic eruption reached the coast; protected areas were affected.'),
  (28, 'Coca River pipeline rupture', '2020-04-07', 11, 'Coca River, Napo/Sucumbios', -0.45, -77.0, 'freshwater', 'pipeline', 7, 15000, 'low', 0, 'closed', 'Pipelines ruptured after riverbank erosion; oil entered the Coca River and affected downstream communities.'),
  (29, 'Bodo spills (Ogoniland)', '2008-08-28', 12, 'Bodo, Rivers State', 4.62, 7.27, 'mixed', 'pipeline', 4, 4144, 'low', 0, 'ongoing', 'Pipeline spills in Ogoniland mangrove creeks led to a long dispute and litigation, with a 2015 settlement for affected communities. Shell reported 4,144 barrels; independent estimates are far higher.'),
  (30, 'Bonga FPSO spill', '2011-12-20', 12, 'Bonga field, offshore Niger Delta', 4.65, 4.62, 'marine', 'offshore_platform', 4, 40000, 'medium', 0, 'closed', 'Release during offloading from a floating production vessel off Nigeria.'),
  (31, 'Wakashio oil spill', '2020-07-25', 13, 'Pointe d''Esny, Mauritius', -20.44, 57.76, 'marine', 'cargo_ship', 3, 6400, 'high', 0, 'closed', 'Bulk carrier ran aground on a coral reef beside protected lagoons and later broke apart.'),
  (32, 'Rena oil spill', '2011-10-05', 14, 'Astrolabe Reef, Bay of Plenty', -37.54, 176.43, 'marine', 'cargo_ship', 3, 2200, 'medium', 0, 'closed', 'Container ship grounded on a reef; widely described as New Zealand''s worst maritime environmental disaster.'),
  (33, 'Hebei Spirit oil spill', '2007-12-07', 15, 'Taean, Yellow Sea', 36.87, 126.05, 'marine', 'tanker', 2, 79900, 'high', 0, 'closed', 'Tanker struck by a drifting crane barge; the largest spill in South Korean history.'),
  (34, 'Sanchi collision', '2018-01-06', 16, 'East China Sea off Shanghai', 28.367, 125.917, 'marine', 'tanker', 2, NULL, 'low', 32, 'closed', 'Iranian tanker collided with a freighter and burned for about a week before sinking; all crew were lost. Position is the collision site. The cargo was about 136,000 tonnes of condensate; the amount spilled is not established.'),
  (35, 'Chennai Ennore oil spill', '2017-01-28', 17, 'Ennore Port, Chennai', 13.24, 80.33, 'marine', 'tanker', 2, 1630, 'medium', 0, 'closed', 'Two vessels collided near Ennore Port; oil spread along Chennai beaches. Official figure is 251 tonnes.'),
  (36, 'MSC Chitra collision', '2010-08-07', 17, 'Off Mumbai, Maharashtra', 18.88, 72.78, 'marine', 'cargo_ship', 2, 6500, 'low', 0, 'closed', 'Container ship collided with another vessel at the entrance to Mumbai harbour, spilling fuel oil.'),
  (37, 'Baghjan oil well blowout', '2020-05-27', 17, 'Tinsukia, Assam', 27.6, 95.38, 'land', 'onshore_well', 1, NULL, 'low', 2, 'closed', 'Gas and oil well blowout in Assam followed by a fire; located near ecologically sensitive wetlands.'),
  (38, 'Jiyeh power station spill', '2006-07-13', 18, 'Jiyeh, Lebanon', 33.65, 35.41, 'marine', 'storage_facility', 8, 90000, 'low', 0, 'closed', 'Fuel oil storage tanks hit in air strikes during the 2006 war; oil spread along the Lebanese coast.'),
  (39, 'Norilsk diesel spill', '2020-05-29', 19, 'Norilsk, Krasnoyarsk Krai', 69.3794, 87.7444, 'land', 'storage_facility', 6, 150000, 'medium', 0, 'closed', 'Fuel tank at a power plant collapsed, discharging diesel onto land and into Arctic rivers; permafrost thaw was implicated.'),
  (40, 'Tlahuelilpan pipeline explosion', '2019-01-18', 3, 'Tlahuelilpan, Hidalgo', 20.07, -99.23, 'land', 'pipeline', 9, NULL, 'medium', 137, 'closed', 'Fuel pipeline illegally tapped by thieves; the leak ignited in a mass explosion that killed 137 people.'),
  (41, 'Bemidji crude oil spill', '1979-08-20', 1, 'Bemidji, Minnesota', 47.65, -94.81, 'land', 'pipeline', 4, 10500, 'medium', 0, 'ongoing', 'Pipeline rupture at a site that became a long-term USGS research location on crude oil in groundwater.'),
  (42, 'Montara oil spill', '2009-08-21', 20, 'Timor Sea', -12.68, 124.55, 'marine', 'offshore_platform', 1, NULL, 'low', 0, 'closed', 'Wellhead platform blowout in the Timor Sea; the leak continued for about ten weeks until a relief well stopped it.'),
  (43, 'Castillo de Bellver', '1983-08-06', 32, 'Off Saldanha Bay, South Africa', -33.276, 17.505, 'marine', 'tanker', 11, 1847160, 'low', 3, 'closed', 'Spanish supertanker caught fire and exploded off the Cape west coast, and split in two. Offshore winds kept most oil from the shore. Volume is the cargo carried, not the amount spilled; much of it burned or sank with the ship.'),
  (44, 'Haven', '1991-04-11', 25, 'Off Genoa, Italy', 44.333, 9.0, 'marine', 'tanker', 11, 1055520, 'low', 6, 'closed', 'Anchored supertanker exploded and burned, and the wreck sank off Genoa. About half the cargo burned and oil drifted along the Ligurian coast. Volume is the cargo carried, not the amount spilled; much of it burned or sank with the ship.'),
  (45, 'Sea Star', '1972-12-19', 26, 'Gulf of Oman', 25.3, 57.567, 'marine', 'tanker', 2, 842950, 'low', 12, 'closed', 'Collided with the tanker Horta Barbosa; both caught fire and Sea Star sank five days later. Volume is the cargo carried, not the amount spilled; much of it burned or sank with the ship.'),
  (46, 'Urquiola', '1976-05-12', 21, 'La Coruna, Spain', 43.367, -8.383, 'marine', 'tanker', 3, 733000, 'low', 1, 'closed', 'Tanker struck the seabed at the port entrance, then exploded and burned. About 25,000 to 30,000 tonnes reached the shore. Volume is the cargo carried, not the amount spilled; much of it burned or sank with the ship.'),
  (47, 'Independenta', '1979-11-15', 30, 'Bosphorus, Istanbul', 41.033, 28.95, 'marine', 'tanker', 2, 696350, 'low', 42, 'closed', 'Romanian tanker collided with a freighter at the southern entrance of the Bosphorus; the explosion and burning oil killed 42 crew. Volume is the cargo carried, not the amount spilled; much of it burned or sank with the ship.'),
  (48, 'Jakob Maersk', '1975-01-29', 31, 'Leixoes, Portugal', 41.15, -8.833, 'marine', 'tanker', 3, 645040, 'low', 7, 'closed', 'Swell dropped the tanker onto the seabed while berthing, rupturing tanks and causing explosions and fire. Volume is the cargo carried, not the amount spilled; much of it burned or sank with the ship.'),
  (49, 'Khark 5', '1989-12-19', 27, 'Atlantic, off Morocco', 34.533, -19.567, 'marine', 'tanker', 7, 513100, 'medium', 0, 'closed', 'Iranian supertanker was damaged in a storm, then exploded and burned, releasing about 70,000 tonnes of crude over 12 days. All 35 crew were rescued.'),
  (50, 'Nova', '1985-12-06', 28, 'Persian Gulf near Kharg Island', 27.196, 51.21, 'marine', 'tanker', 2, 513100, 'low', 0, 'closed', 'Laden supertanker collided with the tanker Magnum at night without running lights, a wartime practice. Five cargo tanks were holed. Fatalities were not reported in the sources consulted.'),
  (51, 'Katina P', '1992-04-17', 29, 'Off Maputo, Mozambique', -25.583, 32.983, 'marine', 'tanker', 7, 25000, 'low', 0, 'closed', 'A freak wave disabled the tanker, which was deliberately grounded off Maputo Bay and later broke in two. Fatalities were not reported in the sources consulted; sources differ on the date (17 or 19 April).'),
  (52, 'Funiwa-5 blowout', '1980-01-17', 12, 'Offshore Niger Delta near Forcados', 5.0, 5.0, 'marine', 'offshore_platform', 1, 200000, 'medium', 0, 'closed', 'Texaco well blew out offshore and the oil ignited on 29 January; the flow stopped on 1 February when the well bridged. Position is approximate.'),
  (53, 'Nowruz oil field spill', '1983-02-10', 28, 'Nowruz field, Persian Gulf', 29.533, 49.583, 'marine', 'offshore_platform', 2, 733000, 'low', 20, 'closed', 'A tanker struck a platform, which tilted. Corrosion and wartime attacks then kept the well leaking until it was capped in September 1983. Deaths include 9 during plugging work in 1985.');
